using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.HighDefinition;using Object=UnityEngine.Object;
public static class FinishSupplyShop {
 const string A="Assets/NewMap/FiveHangars/FinishedShop";static Transform shop;static Material wall,wood,floor,roof,steel,atlas;static Dictionary<string,string> paths;static int serial;static Mesh cube;
 static Transform Group(string name,Transform p){var g=new GameObject(name);g.transform.SetParent(p,false);return g.transform;}
 static Material Material(string n,Color c,Texture albedo=null,Texture normal=null,float smooth=.15f){var m=new Material(Shader.Find("HDRP/Lit")){name=n};m.SetColor("_BaseColor",c);m.SetFloat("_Smoothness",smooth);if(albedo)m.SetTexture("_BaseColorMap",albedo);if(normal){m.SetTexture("_NormalMap",normal);m.EnableKeyword("_NORMALMAP_TANGENT_SPACE");}m.enableInstancing=true;HDMaterial.ValidateMaterial(m);AssetDatabase.CreateAsset(m,A+"/"+n+".mat");return m;}
 static GameObject Box(string n,Transform p,Vector3 pos,Vector3 size,Material mat,bool collide=false){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(p,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<MeshRenderer>().sharedMaterial=mat;if(!collide)Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static void Beam(Transform parent,Vector3 a,Vector3 b,float width,Material mat){var g=Box("Timber trim",parent,(a+b)*.5f,new Vector3(width,(b-a).magnitude,width),mat);g.transform.localRotation=Quaternion.FromToRotation(Vector3.up,b-a);}
 static GameObject Stock(string name,Transform parent,Vector3 local,float yaw=0,float height=0){var source=AssetDatabase.LoadAssetAtPath<GameObject>(paths[name]);var g=(GameObject)PrefabUtility.InstantiatePrefab(source,parent);g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.Euler(0,yaw,0);if(height>0){var rs=g.GetComponentsInChildren<Renderer>();Bounds b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);g.transform.localScale*=height/b.size.y;}
  var renderers=g.GetComponentsInChildren<Renderer>();Bounds bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);var offset=parent.InverseTransformVector(new Vector3(-bounds.center.x+parent.position.x,-bounds.min.y+parent.position.y,-bounds.center.z+parent.position.z));g.transform.localPosition=local+offset;
  foreach(var r in renderers)r.sharedMaterials=r.sharedMaterials.Select(m=>m.name.StartsWith("TFP_Atlas_1A")?atlas:m).ToArray();return g;}
 static bool Counter(Vector3 v)=>Mathf.Abs(v.x)<3.81f&&v.z>1.49f&&v.z<2.72f&&v.y>.18f&&v.y<2.04f;
 static Vector2 UV(Vector3 v,Vector3 n){var a=new Vector3(Mathf.Abs(n.x),Mathf.Abs(n.y),Mathf.Abs(n.z));return a.y>=a.x&&a.y>=a.z?new Vector2(v.x,v.z)*.45f:a.x>a.z?new Vector2(v.z,v.y)*.55f:new Vector2(v.x,v.y)*.55f;}
 static void RefinishShell(){foreach(var r in shop.GetComponentsInChildren<MeshRenderer>().Where(r=>!r.GetComponent<TMPro.TMP_Text>()).ToArray()){
   var mf=r.GetComponent<MeshFilter>();if(!mf)continue;var old=mf.sharedMesh;var mesh=Object.Instantiate(old);mesh.name="Textured shop shell";var vertices=mesh.vertices;for(int i=0;i<vertices.Length;i++)if(Counter(vertices[i]))vertices[i].y*=.57f;mesh.vertices=vertices;var normals=mesh.normals;mesh.uv=vertices.Select((v,i)=>UV(v,normals[i])).ToArray();var groups=new Dictionary<Material,List<int>>();for(int s=0;s<old.subMeshCount;s++){var mat=r.sharedMaterials[s];var tri=old.GetTriangles(s);for(int k=0;k<tri.Length;k+=3){var avg=(vertices[tri[k]]+vertices[tri[k+1]]+vertices[tri[k+2]])/3;Material target=avg.y<.18f?floor:mat.name.Contains("roof")?roof:mat.name.Contains("oak")?wood:wall;if(!groups.ContainsKey(target))groups.Add(target,new List<int>());groups[target].AddRange(new[]{tri[k],tri[k+1],tri[k+2]});}}mesh.subMeshCount=groups.Count;int index=0;foreach(var g in groups)mesh.SetTriangles(g.Value,index++);mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,A+"/Shop shell "+(++serial)+".asset");mf.sharedMesh=mesh;r.sharedMaterials=groups.Keys.ToArray();
  }
  foreach(var c in shop.GetComponentsInChildren<MeshCollider>()){var mesh=Object.Instantiate(c.sharedMesh);mesh.name="Shop collision with accessible counter";var v=mesh.vertices;for(int i=0;i<v.Length;i++)if(Counter(v[i]))v[i].y*=.57f;mesh.vertices=v;mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,A+"/Shop collision.asset");c.sharedMesh=mesh;}
 }
 static MeshRenderer Combine(Transform section,MeshRenderer[] rs,string name){var mats=rs.SelectMany(r=>r.sharedMaterials).Distinct().ToArray();var parts=new List<Mesh>();foreach(var mat in mats){var instances=new List<CombineInstance>();foreach(var r in rs){var mesh=r.GetComponent<MeshFilter>().sharedMesh;for(int s=0;s<mesh.subMeshCount;s++)if(r.sharedMaterials[s]==mat)instances.Add(new CombineInstance{mesh=mesh,subMeshIndex=s,transform=section.worldToLocalMatrix*r.transform.localToWorldMatrix});}var m=new Mesh{indexFormat=IndexFormat.UInt32};m.CombineMeshes(instances.ToArray(),true,true);parts.Add(m);}var result=new Mesh{name=name,indexFormat=IndexFormat.UInt32};result.CombineMeshes(parts.Select(m=>new CombineInstance{mesh=m,transform=Matrix4x4.identity}).ToArray(),false,false);result.RecalculateBounds();AssetDatabase.CreateAsset(result,A+"/Display "+(++serial)+".asset");foreach(var m in parts)Object.DestroyImmediate(m);var g=Group(name,section);g.gameObject.AddComponent<MeshFilter>().sharedMesh=result;var renderer=g.gameObject.AddComponent<MeshRenderer>();renderer.sharedMaterials=mats;return renderer;}
 static void Bake(Transform section){var originals=section.Cast<Transform>().ToArray();var renderers=section.GetComponentsInChildren<MeshRenderer>();var lods=new LOD[2];for(int level=0;level<2;level++){var selected=renderers.Where(r=>{var lod=r.GetComponentInParent<LODGroup>();if(!lod)return true;var ls=lod.GetLODs();return ls[level==0?0:ls.Length-1].renderers.Contains(r);}).ToArray();lods[level]=new LOD(level==0?.24f:.02f,new Renderer[]{Combine(section,selected,"Combined display LOD "+level)});}
  var ci=section.GetComponentsInChildren<BoxCollider>().Select(b=>new CombineInstance{mesh=cube,transform=section.worldToLocalMatrix*b.transform.localToWorldMatrix*Matrix4x4.TRS(b.center,Quaternion.identity,b.size)}).ToArray();if(ci.Length>0){var m=new Mesh{name="Shop fixtures collision",indexFormat=IndexFormat.UInt32};m.CombineMeshes(ci,true,true);AssetDatabase.CreateAsset(m,A+"/Fixture collision "+(++serial)+".asset");section.gameObject.AddComponent<MeshCollider>().sharedMesh=m;}
  foreach(var t in originals)Object.DestroyImmediate(t.gameObject);var group=section.gameObject.AddComponent<LODGroup>();group.SetLODs(lods);group.RecalculateBounds();}
 static void Label(string content,Transform parent,Vector3 pos,float size,Vector2 rect){var g=Group(content,parent);g.localPosition=pos;g.localRotation=Quaternion.Euler(0,180,0);var text=g.gameObject.AddComponent<TMPro.TextMeshPro>();text.text=content;text.fontSize=size;text.rectTransform.sizeDelta=rect;text.alignment=TMPro.TextAlignmentOptions.Center;text.color=new Color(.94f,.86f,.66f);}
