  var boards=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/NewMap/TallHangar/WeatheredGreyBoards_Albedo.png");var oak=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/NewMap/Textures/Oak_Albedo.png");var normal=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/NewMap/Textures/Oak_Normal.png");wall=Material("Cream weatherboard siding",new Color(.8f,.7f,.5f),boards);wood=Material("Oiled oak shop joinery",new Color(.68f,.47f,.27f),oak,normal);floor=Material("Worn timber floorboards",new Color(.59f,.44f,.3f),boards);steel=Material("Shop dark iron",new Color(.18f,.22f,.24f),null,null,.34f);steel.SetFloat("_Metallic",.6f);EditorUtility.SetDirty(steel);
