  atlas=Material("Textured farm stock and cottage",Color.white,AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/NewMap/Textures/TFP_Atlas_1A.png"));foreach(var r in area.GetComponentsInChildren<MeshRenderer>())r.sharedMaterials=r.sharedMaterials.Select(m=>m.name.StartsWith("TFP_Atlas_1A")?atlas:m).ToArray();RefinishShell();
