  AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.gameObject.scene);Directory.CreateDirectory("output/NewMap/FinishedShop");string report="Shop/cottage atlas textured; shop shell has weatherboard, physical-scale UVs, timber floor/joinery, painted metal roof, closed gables and canopy. Counter lowered to ~1.15m. Stocked shelves contain sacks, seed bags, crates, shovels, rake, sledgehammer, hammers, handsaws, hand rake, broom and bucket. Fixtures/stock combined into four sections with two LODs each. Purchases remain deferred.";File.WriteAllText("output/NewMap/FinishedShop/summary.txt",report);return report;
